    internal static bool Polish => CultureInfo.CurrentUICulture.TwoLetterISOLanguageName == "pl";

    public static string Get(string key) => Strings.TryGetValue(key, out var s) ? (Polish ? s.Pl : s.En) : key;

    public static string Format(string key, params object?[] args) => string.Format(Get(key), args);

    /// <summary>"5 min ago", "3 h ago", "yesterday", "4 d ago".</summary>
    public static string Ago(DateTime then, DateTime now)
    {
        var span = now - then;
        if (span.TotalMinutes < 1) return Get("AgoNow");
        if (span.TotalHours < 1) return Format("AgoMinutes", (int)span.TotalMinutes);
        if (span.TotalDays < 1) return Format("AgoHours", (int)span.TotalHours);
        return (int)span.TotalDays == 1 ? Get("AgoDay") : Format("AgoDays", (int)span.TotalDays);
    }

    internal static IEnumerable<string> Keys => Strings.Keys;
}

/// <summary>XAML: Text="{l:L Key}".</summary>
[MarkupExtensionReturnType(typeof(string))]
public sealed class LExtension(string key) : MarkupExtension
{
    public override object ProvideValue(IServiceProvider serviceProvider) => Loc.Get(key);
}

/// <summary>ComboBox item with a value and a localized label.</summary>
public sealed record Choice(object? Value, string Text)
{
    public override string ToString() => Text;

    public static object? Get(ComboBox box) => (box.SelectedItem as Choice)?.Value;

    public static void Select(ComboBox box, object? value) =>
        box.SelectedItem = box.Items.OfType<Choice>().FirstOrDefault(c => Equals(c.Value, value)) ?? box.Items.OfType<Choice>().FirstOrDefault();
}
